replace:
--tap: 48px;
--radius: 16px;
--border-strong: #c9bdb0;
--accent-hover: color-mix(in srgb, var(--accent) 85%, black);
--shadow-1: 0 1px 2px rgb(55 45 30 / 0.025);
--shadow-2: 0 4px 12px rgb(0 0 0 / 0.08);
--backdrop: rgb(45 38 31 / 0.42);

/* Type scale: five steps only. */
--fs-xs: 0.75rem;
--fs-sm: 0.875rem;
--fs-md: 1rem;
--fs-lg: 1.15rem;
--fs-xl: 1.5rem;

/* Motion: durations and easings used across the interface. */
--dur-1: 90ms;
--dur-2: 200ms;
--dur-3: 320ms;
--dur-4: 400ms;
--dur-theme: 1100ms;
--ease-out: cubic-bezier(0.2, 0.8, 0.2, 1);
--ease-theme: cubic-bezier(0.65, 0.05, 0.2, 1);

find:
h1 {
  font-family: Georgia, 'Times New Roman', serif;
  font-size: 2rem;
  font-weight: 400;
  letter-spacing: -0.035em;
}

h2 { font-size: 1.2rem; }

replace:
h1 {
  font-family: Georgia, 'Times New Roman', serif;
  font-size: var(--fs-xl);
  font-weight: 400;
  letter-spacing: -0.035em;
  text-wrap: balance;
}

h2 {
  font-size: var(--fs-lg);
  text-wrap: balance;
}

find:
  border-radius: 16px;
  background: var(--surface);
  color: var(--text);
}

dialog.sheet::backdrop {
  background: rgb(45 38 31 / 0.42);
}

replace:
  border-radius: var(--radius);
  background: var(--surface);
  color: var(--text);
}

dialog.sheet::backdrop {
  background: var(--backdrop);
}
